1	import * as THREE from 'three';
2	import { shared, weatherU } from '../core/shared';
3	import { CONFIG } from '../config';
4	
5	type Mat = THREE.Material;
6	
7	/* Cửa sổ nhà cao tầng sinh bằng shader theo tọa độ thế giới (không kéo giãn khi đổi chiều cao) */
8	export function patchWindows(mat: Mat) {
9	  mat.customProgramCacheKey = () => 'windows';
10	  mat.onBeforeCompile = (sh) => {
11	    sh.uniforms.uNight = shared.uNight;
12	    sh.vertexShader = sh.vertexShader
13	      .replace('#include <common>', '#include <common>\nvarying vec3 vBPos; varying vec3 vBNrm;')
14	      .replace('#include <fog_vertex>', `#include <fog_vertex>
15	        { vec4 bp = vec4(transformed, 1.0); vec3 bn = objectNormal;
16	        #ifdef USE_INSTANCING
17	          bp = instanceMatrix * bp; bn = mat3(instanceMatrix) * bn;
18	        #endif
19	          vBPos = (modelMatrix * bp).xyz; vBNrm = normalize(mat3(modelMatrix) * bn); }`);
20	    sh.fragmentShader = sh.fragmentShader
21	      .replace('#include <common>', `#include <common>
22	        varying vec3 vBPos; varying vec3 vBNrm; uniform float uNight;
23	        float bHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
24	        float winMask(out vec2 cell){
25	          float side = 1.0 - step(0.6, abs(vBNrm.y));
26	          float along = abs(vBNrm.x) > 0.5 ? vBPos.z : vBPos.x;
27	          vec2 g = vec2(along / 3.2, vBPos.y / 3.4);
28	          cell = floor(g); vec2 f = fract(g);
29	          return side * step(0.16, f.x) * step(f.x, 0.84) * step(0.22, f.y) * step(f.y, 0.82) * step(5.5, vBPos.y);
30	        }`)
31	      .replace('#include <map_fragment>', `#include <map_fragment>
32	        { vec2 cl; float wm = winMask(cl);
33	          diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.20, 0.29, 0.36), wm * 0.82); }`)
34	      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
35	        { vec2 cl; float wm = winMask(cl);
36	          float h = bHash(cl + floor(vBPos.xz * 0.02) * 7.13);
37	          vec3 lit = mix(vec3(1.0, 0.78, 0.46), vec3(0.75, 0.88, 1.0), step(0.8, h));
38	          totalEmissiveRadiance += wm * step(0.42, h) * lit * uNight * 1.3; }`);
39	  };
40	}
41	
42	/* ======================================================================
43	   Shader bổ sung cho các cầu: vân bê tông, vệt nước bám, LED đổi màu theo bảng màu / pattern
44	   ====================================================================== */
45	export const LED_PALETTES = {
46	  sea: [[0.10, 0.35, 1.00], [0.55, 0.18, 1.00], [1.00, 0.22, 0.62], [0.12, 1.00, 0.55]],  // xanh dương → tím → hồng → xanh lá
47	  sail: [[1.00, 0.08, 0.10], [1.00, 0.20, 0.50], [0.60, 0.16, 1.00], [0.12, 0.38, 1.00]], // đỏ → hồng → tím → xanh ("cánh buồm đỏ")
48	  rainbow: [[1.00, 0.12, 0.10], [1.00, 0.78, 0.10], [0.10, 1.00, 0.35], [0.15, 0.40, 1.00]] // cầu vồng (Cầu sông Hàn)
49	};
50	export type PaletteName = keyof typeof LED_PALETTES;
51	const glslVec3 = (c: number[]) => `vec3(${c.map((v) => v.toFixed(2)).join(', ')})`;
52	
53	export interface BridgePatchOptions {
54	  noise?: boolean;
55	  wet?: boolean;
56	  led?: number;                  // cường độ
57	  mode?: 0 | 1;                  // 0: theo trục cầu, 1: đèn hắt tháp
58	  palette?: PaletteName;
59	  pattern?: { value: number };   // uniform chọn pattern
60	  originX?: number;              // sóng chạy ra xa điểm này
61	  originZ?: number;
62	  floodTop?: number;             // m, cho mode 1
63	  floodBase?: number;
64	  weather?: boolean;             // mặt ướt khi mưa: đọc weatherU.uWet (0 = không đổi gì)
65	  sag?: 'cable' | 'hanger';      // võng cáp chủ Thuận Phước khi nóng (weather/summer.ts): đọc weatherU.uSagTp (0 = không đổi gì); hanger chỉ dịch đầu trên
66	  sway?: SwayKind;               // dây lắc theo gió (chỉ InstancedMesh dựng bằng segmentMatrix): đọc weatherU.uSwayTp/Ttl/Sh (0 = không đổi gì)
67	}
68	export type SwayKind = 'tp' | 'ttl' | 'sh';
69	const SWAY_U = { tp: weatherU.uSwayTp, ttl: weatherU.uSwayTtl, sh: weatherU.uSwaySh };
70	
71	/* Dây lắc theo gió (mục 4.5): dịch SAU khi nhân instanceMatrix/modelMatrix (không gian thế giới — segmentMatrix co bán kính nên dịch cục bộ bị thu nhỏ).
72	   Dạng sin(π·t), t = position.y + 0.5 của CylinderGeometry (hai đầu cố định) — hình trụ phải có heightSegments > 1 (CONFIG.weather.wind.cableSegs), dây 1 đoạn thì sin = 0 ở mọi đỉnh, không lắc. Hướng chính: thành phần gió vuông góc với dây, thêm 35 % vuông góc thứ hai (quỹ đạo elip).
73	   Biên độ (m, đã phóng đại) do weather/wind.ts tính; = 0 thì nhánh không chạy (ảnh preset `now` trùng từng điểm ảnh). */
74	const swayVertex = (omega: number) => `#include <project_vertex>
75	  #ifdef USE_INSTANCING
76	  if (uSway > 0.0) {
77	    vec3 swAx = mat3(modelMatrix) * instanceMatrix[1].xyz; float swLen = length(swAx); swAx /= swLen;
78	    vec3 swW = vec3(uWindDir.x, 0.0, uWindDir.y), swD = swW - swAx * dot(swW, swAx); float swL = length(swD);
79	    swD = swL > 1e-3 ? swD / swL : vec3(0.0, 1.0, 0.0);
80	    vec3 swE = cross(swAx, swD), swC = (modelMatrix * vec4(instanceMatrix[3].xyz, 1.0)).xyz;
81	    float swPh = dot(swC, vec3(0.071, 0.023, 0.113)), swT = clamp(position.y + 0.5, 0.0, 1.0);
82	    float swA = sin(3.14159265 * swT) * uSway * min(1.0, swLen / ${CONFIG.weather.wind.refLen.toFixed(1)});
83	    vec3 swDisp = swA * (swD * sin(uTime * ${omega.toFixed(2)} + swPh) + swE * 0.35 * sin(uTime * ${(omega * 1.37).toFixed(2)} + swPh * 1.7));
84	    mvPosition.xyz += mat3(viewMatrix) * swDisp; gl_Position = projectionMatrix * mvPosition;
85	  }
86	  #endif`;
87	/* Võng cáp chủ khi nóng (mục 4.7): dịch y theo Δf·sin(π·u), u = vị trí dọc nhịp chính (ngoài nhịp chính = 0). Hanger: chỉ đầu trên (position.y = −0,5, xem segmentMatrix(top, bot)) đi xuống. */
88	const sagVertex = (kind: 'cable' | 'hanger') => `
89	  if (uSagTp != 0.0) {
90	    vec4 sgL = vec4(transformed, 1.0);
91	    #ifdef USE_INSTANCING
92	      sgL = instanceMatrix * sgL;
93	    #endif
94	    float sgX = (modelMatrix * sgL).x, sgU = clamp((sgX + ${(CONFIG.thuanPhuoc.mainSpan / 2).toFixed(2)}) / ${CONFIG.thuanPhuoc.mainSpan.toFixed(2)}, 0.0, 1.0);
95	    float sgW = ${kind === 'hanger' ? 'clamp(0.5 - position.y, 0.0, 1.0)' : '1.0'};
96	    mvPosition.xyz += mat3(viewMatrix) * vec3(0.0, -uSagTp * sin(3.14159265 * sgU) * sgW, 0.0); gl_Position = projectionMatrix * mvPosition;
97	  }`;
98	export function bridgePatch<M extends Mat>(mat: M, opt: BridgePatchOptions): M {
99	  const pal = LED_PALETTES[opt.palette || 'sea'];
100	  const key = ['bp', opt.noise ? 1 : 0, opt.wet ? 1 : 0, opt.led || 0, opt.mode || 0, opt.palette || 'sea',
101	    opt.pattern ? 1 : 0, opt.originX ?? 'n', opt.originZ ?? 'n', opt.floodTop ?? 95, opt.floodBase ?? 12].join('-') + (opt.weather ? '-w' : '') + (opt.sway ? '-s' + opt.sway : '') + (opt.sag ? '-g' + opt.sag : '');   // tắt weather/sway: key cũ giữ nguyên
102	  mat.customProgramCacheKey = () => key;
103	  mat.onBeforeCompile = (sh) => {
104	    sh.uniforms.uTime = shared.uTime; sh.uniforms.uNight = shared.uNight;
105	    if (opt.pattern) sh.uniforms.uPattern = opt.pattern;
106	    if (opt.weather) sh.uniforms.uWet = weatherU.uWet;
107	    if (opt.sag) sh.uniforms.uSagTp = weatherU.uSagTp;
108	    if (opt.sway) { sh.uniforms.uSway = SWAY_U[opt.sway]; sh.uniforms.uWindDir = weatherU.uWindDir; }
109	    sh.vertexShader = sh.vertexShader
110	      .replace('#include <common>', '#include <common>\nvarying vec3 vBW;' + (opt.sway ? '\nuniform float uTime; uniform float uSway; uniform vec2 uWindDir;' : '') + (opt.sag ? '\nuniform float uSagTp;' : ''))
111	      .replace('#include <project_vertex>', (opt.sway ? swayVertex(CONFIG.weather.wind[opt.sway].omega) : '#include <project_vertex>') + (opt.sag ? sagVertex(opt.sag) : ''))
112	      .replace('#include <fog_vertex>', `#include <fog_vertex>
113	        { vec4 bw = vec4(transformed, 1.0);
114	        #ifdef USE_INSTANCING
115	          bw = instanceMatrix * bw;
116	        #endif
117	          vBW = (modelMatrix * bw).xyz; }`);
118	    let frag = sh.fragmentShader.replace('#include <common>', `#include <common>
119	      varying vec3 vBW; uniform float uTime; uniform float uNight; ${opt.pattern ? 'uniform float uPattern;' : ''} ${opt.weather ? 'uniform float uWet;' : ''}
120	      float bpHash(vec3 p){ p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
121	      float bpNoise(vec3 x){ vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
122	        return mix(mix(mix(bpHash(i), bpHash(i + vec3(1,0,0)), f.x), mix(bpHash(i + vec3(0,1,0)), bpHash(i + vec3(1,1,0)), f.x), f.y),
123	                   mix(mix(bpHash(i + vec3(0,0,1)), bpHash(i + vec3(1,0,1)), f.x), mix(bpHash(i + vec3(0,1,1)), bpHash(i + vec3(1,1,1)), f.x), f.y), f.z); }
124	      vec3 bpPal(float s){ s = fract(s) * 4.0; float i = floor(s), f = smoothstep(0.0, 1.0, fract(s));
125	        vec3 c0 = ${glslVec3(pal[0])}, c1 = ${glslVec3(pal[1])}, c2 = ${glslVec3(pal[2])}, c3 = ${glslVec3(pal[3])};
126	        vec3 a = i < 1.0 ? c0 : i < 2.0 ? c1 : i < 3.0 ? c2 : c3;
127	        vec3 b = i < 1.0 ? c1 : i < 2.0 ? c2 : i < 3.0 ? c3 : c0;
128	        return mix(a, b, f); }`);
129	    let after = '';
130	    if (opt.noise) after += `
131	        float bpN = bpNoise(vBW * 0.16) * 0.6 + bpNoise(vBW * 0.85) * 0.4;
132	        diffuseColor.rgb *= 0.86 + 0.22 * bpN;`;
133	    if (opt.wet) after += `
134	        { vec3 wetC = vBW.y < -0.4 ? vec3(0.42, 0.44, 0.40) : vec3(0.56, 0.60, 0.52);
135	          diffuseColor.rgb *= mix(wetC, vec3(1.0), smoothstep(1.7, 2.4, vBW.y)); }`;
136	    // Mặt ướt: uWet = 0 thì nhánh không chạy (ảnh preset `now` trùng từng điểm ảnh); mặt hướng lên ướt hơn mặt đứng
137	    if (opt.weather) after += `
138	        float bpWet = 0.0;
139	        if (uWet > 0.0) { bpWet = uWet * mix(0.6, 1.0, step(0.0, vBW.y)); diffuseColor.rgb *= 1.0 - ${(1 - CONFIG.weather.wetness.bridgeDarken).toFixed(3)} * bpWet; }`;
140	    if (after) frag = frag.replace('#include <map_fragment>', `#include <map_fragment>${after}`);
141	    if (opt.noise) frag = frag.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
142	        roughnessFactor = clamp(roughnessFactor + (bpN - 0.5) * 0.18, 0.0, 1.0);`);
143	    if (opt.weather) frag = frag.replace('#include <lights_physical_fragment>', `if (uWet > 0.0) roughnessFactor = mix(roughnessFactor, min(roughnessFactor, ${CONFIG.weather.wetness.bridgeRough.toFixed(3)}), bpWet);
144	        #include <lights_physical_fragment>`);
145	    if (opt.led) {
146	      const L = opt.led.toFixed(2), fTop = (opt.floodTop ?? 95).toFixed(1), fBase = (opt.floodBase ?? 12).toFixed(1);
147	      // originX: sóng chạy ra xa điểm này theo trục X; thêm originZ: theo khoảng cách ngang (dùng cho nhịp quay)
148	      const coord = opt.originZ !== undefined ? `length(vec2(vBW.x - (${opt.originX.toFixed(1)}), vBW.z - (${opt.originZ.toFixed(1)})))`
149	        : opt.originX !== undefined ? `abs(vBW.x - (${opt.originX.toFixed(1)}))` : 'vBW.x';
150	      let body: string;
151	      if (opt.mode === 1 && !opt.pattern) {          // tháp: đèn hắt từ chân lên, dải màu chạy lên đỉnh
152	        body = `float s = vBW.y * 0.006 + vBW.x * 0.0025 - uTime * 0.07;
153	           float flood = 0.35 + 0.65 * smoothstep(${fTop}, ${fBase}, vBW.y);
154	           float band = 0.75 + 0.25 * sin(vBW.y * 0.25 - uTime * 2.0);
155	           totalEmissiveRadiance += bpPal(s) * flood * band * uNight * ${L};`;
156	      } else if (!opt.pattern) {                     // cáp / dải đèn: màu trượt dọc cầu, xung sáng chạy
157	        body = `float s = ${coord} * 0.0025 - uTime * 0.07;
158	           float pulse = 0.55 + 0.45 * sin(${coord} * 0.045 - uTime * 2.2);
159	           totalEmissiveRadiance += bpPal(s) * pulse * uNight * ${L};`;
160	      } else {                                       // có chọn pattern: 0 tĩnh, 1 chuyển màu chậm, 2 sóng màu chạy dọc dây
161	        const c = opt.mode === 1 ? 'vBW.y' : coord;
162	        const flood = opt.mode === 1 ? `0.35 + 0.65 * smoothstep(${fTop}, ${fBase}, vBW.y)` : '1.0';
163	        body = `float s; float pulse;
164	           if (uPattern < 0.5) { s = 0.06; pulse = 1.0; }
165	           else if (uPattern < 1.5) { s = uTime * 0.025; pulse = 1.0; }
166	           else { s = ${c} * 0.004 - uTime * 0.09; pulse = 0.5 + 0.5 * sin(${c} * 0.06 - uTime * 2.6); }
167	           totalEmissiveRadiance += bpPal(s) * pulse * (${flood}) * uNight * ${L};`;
168	      }
169	      frag = frag.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>\n{ ${body} }`);
170	    }
171	    sh.fragmentShader = frag;
172	  };
173	  return mat;
174	}
