1	import * as THREE from 'three';
2	import { Water } from 'three/addons/objects/Water.js';
3	import { scene } from './renderer';
4	import { rng } from '../common/math';
5	
6	/* ============================ Mặt nước sông Hàn ============================ */
7	export let water: Water;
8	
9	function makeWaterNormals() {
10	  const S = 256, d = new Uint8Array(S * S * 4);
11	  // Tổng nhiều sóng tần số nguyên, pha ngẫu nhiên → lát gạch liền mạch, không lộ hoa văn
12	  const waves: [number, number, number, number][] = []; const wr = rng(77);
13	  for (let i = 0; i < 28; i++) {
14	    const fx = Math.round((wr() - 0.5) * 2 * (3 + i)), fy = Math.round((wr() - 0.5) * 2 * (3 + i));
15	    if (fx === 0 && fy === 0) continue;
16	    waves.push([fx, fy, wr() * Math.PI * 2, 1 / Math.hypot(fx, fy)]);
17	  }
18	  const hgt = (x: number, y: number) => {
19	    const u = x / S * Math.PI * 2, v = y / S * Math.PI * 2; let h = 0;
20	    for (const [fx, fy, ph, a] of waves) h += Math.sin(u * fx + v * fy + ph) * a;
21	    return h;
22	  };
23	  // Lưới độ cao tính một lần, rộng thêm 1 điểm ảnh mỗi bên (cùng công thức nên trùng từng byte với cách gọi hgt 4 lần/điểm ảnh, nhanh ≈ 3,5×; D-018)
24	  const N = S + 2, H = new Float64Array(N * N);
25	  for (let y = -1; y <= S; y++) for (let x = -1; x <= S; x++) if (!((x < 0 || x === S) && (y < 0 || y === S))) H[(y + 1) * N + x + 1] = hgt(x, y);
26	  const at = (x: number, y: number) => H[(y + 1) * N + x + 1];
27	  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
28	    const dx = (at(x + 1, y) - at(x - 1, y)) * 6, dy = (at(x, y + 1) - at(x, y - 1)) * 6;
29	    const l = Math.hypot(dx, dy, 1), i = (y * S + x) * 4;
30	    d[i] = (-dx / l * 0.5 + 0.5) * 255; d[i + 1] = (-dy / l * 0.5 + 0.5) * 255; d[i + 2] = (1 / l * 0.5 + 0.5) * 255; d[i + 3] = 255;
31	  }
32	  const t = new THREE.DataTexture(d, S, S, THREE.RGBAFormat);
33	  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.needsUpdate = true;
34	  return t;
35	}
36	export function buildWater() {
37	  const g = new THREE.PlaneGeometry(40000, 40000);
38	  water = new Water(g, {
39	    textureWidth: 512, textureHeight: 512, waterNormals: makeWaterNormals(),
40	    sunDirection: new THREE.Vector3(0, 1, 0), sunColor: 0xffffff, waterColor: 0x2c5a4f,
41	    distortionScale: 2.4, fog: true
42	  });
43	  water.rotation.x = -Math.PI / 2;
44	  water.material.uniforms.size.value = 0.6;
45	  scene.add(water);
46	  // Phản chiếu theo bậc chất lượng (D-018): every = 1 như gốc (vẽ lại cả cảnh vào target 512² mỗi khung), n > 1 vẽ mỗi n khung (giữ ảnh cũ ở giữa),
47	  // 0 = tắt: đổi sampler sang texture 1×1 màu sương (màu trời gần chân trời) — chỉ đổi giá trị uniform, không biên dịch lại
48	  const draw = water.onBeforeRender, mirror = water.material.uniforms.mirrorSampler;
49	  const mirrorTex = mirror.value as THREE.Texture, flatTex = new THREE.DataTexture(new Uint8Array(4), 1, 1);
50	  let n = 0;
51	  water.onBeforeRender = function (...args: Parameters<typeof draw>) {
52	    const every = reflectState.every;
53	    if (every > 0) {
54	      if (mirror.value !== mirrorTex) mirror.value = mirrorTex;
55	      if (every === 1 || n++ % every === 0) draw.apply(this, args);
56	      return;
57	    }
58	    if (mirror.value !== flatTex) mirror.value = flatTex;
59	    const c = (scene.fog as THREE.FogExp2).color, d = flatTex.image.data as Uint8Array;
60	    const r = Math.round(c.r * 255), g = Math.round(c.g * 255), b = Math.round(c.b * 255);
61	    if (d[0] !== r || d[1] !== g || d[2] !== b) { d[0] = r; d[1] = g; d[2] = b; d[3] = 255; flatTex.needsUpdate = true; }
62	  };
63	}
64	export const reflectState = { every: 1 };
